/*
 * @file
 * @brief Firmware resolution over the integrator's registry.
 *
 * The CMSIS port does not decide where firmware lives: the integrator
 * registers the blobs it carries (embedded arrays generated by
 * scripts/gen_firmware_array.py, a file system, ...) under their
 * driver image names, and this unit resolves the NetBSD firmload(9)
 * calls against that table.
 *
 * @author zhugengyu
 * @date 22.09.2026
 */

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <port/port.h>

#include "wlan_port_cmsis.h"

#ifndef WLAN_PORT_CMSIS_FW_MAX
#define WLAN_PORT_CMSIS_FW_MAX 4
#endif

struct registered_firmware {
	const char *rf_name;
	const uint8_t *rf_data;
	size_t rf_size;
};

static struct registered_firmware wlan_firmwares[WLAN_PORT_CMSIS_FW_MAX];

int wlan_port_firmware_register(const char *name, const uint8_t *data,
	size_t size) {
	struct registered_firmware *rf;

	for (rf = wlan_firmwares; rf < &wlan_firmwares[WLAN_PORT_CMSIS_FW_MAX];
	    rf++) {
		if (rf->rf_name == NULL) {
			rf->rf_name = name;
			rf->rf_data = data;
			rf->rf_size = size;
			return 0;
		}
	}
	return -1;
}

int wlan_port_firmware_get(const char *name, struct wlan_firmware *fw) {
	const struct registered_firmware *rf;

	for (rf = wlan_firmwares; rf < &wlan_firmwares[WLAN_PORT_CMSIS_FW_MAX];
	    rf++) {
		if (rf->rf_name != NULL && strcmp(rf->rf_name, name) == 0) {
			fw->data = rf->rf_data;
			fw->size = rf->rf_size;
			return 0;
		}
	}
	return -1;
}

/* ------------------------------------------------------------------
 * NetBSD firmload(9) API over the registry.
 */
#include <dev/firmload.h>

/* the compat malloc/free macros must not intercept the host calls */
#undef malloc
#undef free

/* The resolved descriptor behind a firmware_handle_t. The NetBSD
 * firmload(9) contract hands the driver an opaque handle that stays
 * valid until firmware_close(); a single firmware image is in flight
 * at a time (urtwn_load_firmware holds sc_write_mtx for the whole
 * load). */
static struct wlan_firmware wlan_fw_desc;

int firmware_open(const char *drv, const char *img, firmware_handle_t *h) {
	const char *name;

	(void) drv; /* the blobs are keyed by the bare image name */
	name = img;
	if (wlan_port_firmware_get(name, &wlan_fw_desc) != 0) {
		return -1;
	}
	*h = &wlan_fw_desc;
	return 0;
}

size_t firmware_get_size(firmware_handle_t h) {
	return h->size;
}

void *firmware_malloc(size_t len) {
	return wlan_osal_alloc(len);
}

int firmware_read(firmware_handle_t h, size_t offset, void *buf, size_t len) {
	if (offset + len > h->size) {
		return -1;
	}
	memcpy(buf, h->data + offset, len);
	return 0;
}

void firmware_close(firmware_handle_t h) {
	(void) h;
}

void firmware_free(void *buf, size_t len) {
	(void) len;
	wlan_osal_free(buf);
}
